const n = (key: string, label: string, dim: string | undefined, unit: string | undefined, def: number | undefined, extra: Partial<CalcInput> = {}): CalcInput => ({
  key, label, ...(dim ? { dim } : {}), ...(unit ? { unit } : {}), ...(def !== undefined ? { default: def } : {}), ...extra,
});
const sel = (key: string, label: string, options: [string, string][], def: string): CalcInput => ({
  key, label, type: "select", options: options.map(([value, l]) => ({ value, label: l })), default: def,
});
const phase = sel("phase", "Phase", [["1", "Single-phase"], ["3", "Three-phase"]], "1");
const AWG = sel("awg", "Conductor size (AWG/kcmil)", ["14", "12", "10", "8", "6", "4", "3", "2", "1", "1/0", "2/0", "3/0", "4/0"].map((s) => [s, s.includes("/") ? s : `${s} AWG`] as [string, string]), "10");
const MAT = sel("material", "Conductor material", [["copper", "Copper"], ["aluminum", "Aluminum"]], "copper");
const T = (key: string, label: string, def: number) => n(key, label, "temperature", "F", def, { units: ["F", "C"] });
const DT = (key: string, label: string, def: number) => n(key, label, "tempDiff", "dF", def);
const CFM = (def: number) => n("cfm", "Airflow", "flow", "cfm", def, { units: ["cfm", "Ls", "m3h"] });

const C = (m: CalculatorMeta) => m;

